B.Vd=new A.o("GPS verification and route capture \u2014 each visit is checked against the customer location, and the route is recorded only during an active visit with explicit user consent, using a native Android foreground service and iOS background location.","\u062a\u0648\u062b\u064a\u0642 \u0628\u0627\u0644\u0640 GPS \u0648\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0645\u0633\u0627\u0631 \u2014 \u0643\u0644 \u0632\u064a\u0627\u0631\u0629 \u0628\u062a\u062a\u0642\u0627\u0631\u0646 \u0628\u0645\u0648\u0642\u0639 \u0627\u0644\u0639\u0645\u064a\u0644\u060c \u0648\u0627\u0644\u0645\u0633\u0627\u0631 \u0628\u064a\u062a\u0633\u062c\u0651\u0644 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0632\u064a\u0627\u0631\u0629 \u0628\u0633 \u0648\u0628\u0645\u0648\u0627\u0641\u0642\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0635\u0631\u064a\u062d\u0629\u060c \u0639\u0628\u0631 foreground service \u0639\u0644\u0649 Android \u0648 background location \u0639\u0644\u0649 iOS.")
B.Yq=new A.o("Visit approval workflow \u2014 submit, approve, reject, reschedule or cancel, with participant approvals and FCM push notifications that deep-link straight to the visit.","\u062f\u0648\u0631\u0629 \u0627\u0639\u062a\u0645\u0627\u062f \u0644\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u2014 \u062a\u0642\u062f\u064a\u0645 \u0648\u0627\u0639\u062a\u0645\u0627\u062f \u0648\u0631\u0641\u0636 \u0648\u0625\u0639\u0627\u062f\u0629 \u062c\u062f\u0648\u0644\u0629 \u0648\u0625\u0644\u063a\u0627\u0621\u060c \u0645\u0639 \u0645\u0648\u0627\u0641\u0642\u0627\u062a \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u064a\u0646 \u0648\u0625\u0634\u0639\u0627\u0631\u0627\u062a FCM \u0628\u062a\u0641\u062a\u062d \u0627\u0644\u0632\u064a\u0627\u0631\u0629 \u0645\u0628\u0627\u0634\u0631\u0629.")
B.Uk=new A.o("Offline-first actions \u2014 start and end actions taken without a connection are stored on the device and replayed automatically; GPS points are uploaded in batches.","\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u062a\u0634\u062a\u063a\u0644 \u0623\u0648\u0641\u0644\u0627\u064a\u0646 \u2014 \u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0628\u062f\u0621 \u0648\u0627\u0644\u0625\u0646\u0647\u0627\u0621 \u0628\u062f\u0648\u0646 \u0625\u0646\u062a\u0631\u0646\u062a \u0628\u062a\u062a\u062e\u0632\u0646 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0648\u062a\u062a\u0628\u0639\u062a \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627\u060c \u0648\u0646\u0642\u0627\u0637 \u0627\u0644\u0640 GPS \u0628\u062a\u062a\u0631\u0641\u0639 \u0639\u0644\u0649 \u062f\u0641\u0639\u0627\u062a.")
